CREATE OR REPLACE FUNCTION public.guard_message_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_path text;
begin
  if not public.is_trusted_writer() then
    new.kind := 'message';
